import * as THREE from 'three/webgpu'
import gsap from 'gsap'

export default function createNode(config, ctx) {
  // Create root container
  const root = new THREE.Group()

  // Load GLB mesh from cache via ctx.glbLoader
  const glbData = ctx.glbLoader.load(config.meshUrl)
  const mesh = glbData.scene

  // Parse placement transforms
  const [px, py, pz] = config.scenePosition || [0, 0, 0]
  const [rx, ry, rz] = config.rotation || [0, 0, 0]
  const [sx, sy, sz] = config.scale || [1, 1, 1]

  // Apply transforms to mesh (positions it in world space)
  mesh.position.set(px, py, pz)
  mesh.rotation.set(rx, ry, rz)
  mesh.scale.set(sx, sy, sz)

  root.add(mesh)
  root.position.set(px, py, pz)

  // Apply cinematic primitives (parallax-scroll, magnetic-cursor, etc.)
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(({ name, params }) => {
      if (ctx.primitives && typeof ctx.primitives[name] === 'function') {
        ctx.primitives[name](root, params)
      }
    })
  }

  // State for hover animation
  let hoverTimeline = null
  const baseY = py

  // Attach event handlers
  root.userData.handlers = {
    onHover() {
      if (hoverTimeline) hoverTimeline.kill()
      hoverTimeline = gsap.to(root.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      })
    },

    onHoverOut() {
      if (hoverTimeline) hoverTimeline.kill()
      hoverTimeline = gsap.to(root.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out'
      })
    },

    onClick() {
      // Selection event; framework emits hub-collection.select
    }
  }

  // Cleanup function
  root.userData.cleanup = () => {
    if (hoverTimeline) {
      hoverTimeline.kill()
    }

    // Dispose all geometries and materials
    mesh.traverse(node => {
      if (node instanceof THREE.Mesh) {
        if (node.geometry) {
          node.geometry.dispose()
        }
        if (node.material) {
          if (Array.isArray(node.material)) {
            node.material.forEach(mat => mat.dispose())
          } else {
            node.material.dispose()
          }
        }
      }
    })
  }

  return root
}
